278.     fn consume_start_inductive(pre: Self, post: Self) {
279.         let head = pre.consumer.get_Idle_0();
280.         assert(post.storage == pre.storage.remove(head));
281.         assert(post.storage.dom() == pre.storage.dom().remove(head));
282.         assert(post.producer == pre.producer);
283.         assert(post.consumer == ConsumerState::Consuming(head));
284.         assert(post.head == pre.head);
285.         assert(post.tail == pre.tail);
286.         assert(post.backing_cells == pre.backing_cells);
287.         lemma_map_remove_domain(pre.storage, head);
288.         assert forall|i: nat| 0 <= i && i < pre.len() implies post.valid_storage_at_idx(i) by {
289.             assert(pre.valid_storage_all());
290.             assert(post.in_active_range(i) == pre.in_active_range(i));
291.             if i == head {
292.                 assert(!post.storage.dom().contains(i));
293.             } else {
294.                 assert(i != head);
295.                 axiom_map_remove_different(pre.storage, i, head);
296.                 assert(post.consumer == ConsumerState::Consuming(head));
297.                 if pre.storage.dom().contains(i) {
298.                     assert(post.storage.dom().contains(i));
299.                     assert(post.storage.index(i) == pre.storage.index(i));
300.                     assert(pre.valid_storage_at_idx(i));
301.                     assert(post.is_checked_out(i) == false);
302.                 } else {
303.                     assert(pre.valid_storage_at_idx(i));
304.                     assert(post.is_checked_out(i));
305.                 }
306.                 assert(pre.is_checked_out(i) == false);
307.                 assert(pre.valid_storage_at_idx(i));
308.             }
309.         }
310.     }
311.     #[inductive(consume_end)]
312.     fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
